addedToArea.action:
count = 0.0;
hybrids = ["human_thrall", "human_thrall2", "paramedic"];
target = null;

for (hybrid in hybrids) {
    var object = area.getObject(hybrid);
    if (object != null) {
        target = object;
        Movement.seek(this, object, 8, true);
    }
}
function canDamage(o){
    return o.attackPower(1, 1, 0, null, false) > 0 && o.getDefense(false, false, false) < 16;
}

object.onFrame:
  count += frames;
if(count >= 9){
    for(o in this.getOverlappingObjects(canDamage)) {
        count -= 9;
        if (hybrids.indexOf(o.info.id) != -1){
            o.heal(10);
            this.removeObject(this.info.id);
        }
    }
}
